package com.kongye.floatball;
import android.content.*;
import android.graphics.*;
import android.os.*;
import java.io.*;
final class RecordingChecks {
    private static int count;private static void check(boolean ok,String label){count++;if(!ok)throw new AssertionError(label);}
    static void run(Context c){count=0;String error="";File gif=null,media=null;try{RecordingSpec s=new RecordingSpec();s.screenW=1080;s.screenH=2520;s.density=420;s.crop=new Rect(120,300,840,1500);s.shortSide=480;s.size();check(s.width==480&&s.height==800,"selected crop aspect and resolution");s.audio="both";s.watermark="测试水印";s.hide=true;RecordingSpec round=RecordingSpec.read(s.write(new Intent()));check(round.crop.equals(s.crop)&&round.audio.equals("both")&&round.hide&&round.watermark.equals(s.watermark),"recording options serialize");s.crop=new Rect(0,0,1080,2520);s.shortSide=1080;s.size();check(s.width%16==0&&s.height%16==0&&Math.max(s.width,s.height)<=1920,"codec aligned size cap");byte[] a={0x10,0x27,0x00,(byte)0x80},b={0x10,0x27,0x00,(byte)0x80},out=new byte[4];check(PcmMix.mix(a,4,b,4,out,4)==4,"mixed PCM size");check((short)((out[0]&255)|(out[1]<<8))==10000,"mixed PCM has headroom");check((short)((out[2]&255)|(out[3]<<8))==-32768,"mixed PCM negative endpoint");
        gif=RecordingFiles.create(c,"gif");Bitmap frame=Bitmap.createBitmap(64,48,Bitmap.Config.ARGB_8888);try(GifWriter writer=new GifWriter(new BufferedOutputStream(new FileOutputStream(gif)),64,48)){for(int color:new int[]{Color.RED,Color.BLUE,Color.GREEN}){frame.eraseColor(color);writer.frame(frame,200);}}frame.recycle();Movie movie=Movie.decodeFile(gif.getPath());check(movie!=null,"streamed GIF decodes");check(movie.width()==64&&movie.height()==48,"GIF dimensions");check(movie.duration()>=500,"GIF frame timings");Bitmap pixels=Bitmap.createBitmap(64,48,Bitmap.Config.ARGB_8888);movie.setTime(0);movie.draw(new Canvas(pixels),0,0);check(Color.red(pixels.getPixel(20,20))>200&&Color.blue(pixels.getPixel(20,20))<40,"GIF first frame color");movie.setTime(220);movie.draw(new Canvas(pixels),0,0);check(Color.blue(pixels.getPixel(20,20))>200,"GIF second frame animates");pixels.recycle();android.net.Uri share=ShareImageProvider.prepareMedia(c,gif);check(c.getContentResolver().getType(share).equals("image/gif"),"GIF sharing MIME");boolean rejected=false;try{c.getContentResolver().openFileDescriptor(share,"w").close();}catch(FileNotFoundException expected){rejected=true;}check(rejected,"GIF share read only");new File(new File(c.getCacheDir(),"shared-images"),share.getLastPathSegment()).delete();media=RecordingFiles.create(c,"mp4");try(OutputStream write=new FileOutputStream(media)){write.write(new byte[]{1,2,3});}share=ShareImageProvider.prepareMedia(c,media);check(c.getContentResolver().getType(share).equals("video/mp4"),"video sharing MIME");try(InputStream in=c.getContentResolver().openInputStream(share)){check(in.read()==1,"video share reads cached bytes");}new File(new File(c.getCacheDir(),"shared-images"),share.getLastPathSegment()).delete();check(RecordingFiles.checked(c,media.getPath()).equals(media),"private recording path accepts owned file");rejected=false;try{RecordingFiles.checked(c,new File(c.getFilesDir(),"other.mp4").getPath());}catch(IOException expected){rejected=true;}check(rejected,"private recording path rejects unrelated file");check(java.util.Arrays.asList(Prefs.ACTIONS).contains("gif_record"),"GIF selectable as tool and gesture");
        }catch(Throwable e){error=e.getClass().getSimpleName()+": "+e.getMessage();}finally{if(gif!=null)gif.delete();if(media!=null)media.delete();}Prefs.of(c).edit().putInt("qa_record_checks",count).putBoolean("qa_record_pass",error.isEmpty()).putString("qa_record_error",error).apply();}
}
